mapper.select:
WHERE d.status = 'on' AND s.status = 'open' AND c.status = 'open' AND (d.audit_status = 'approved' OR d.audit_status IS NULL)
AND (d.name LIKE CONCAT('%', #{req.keyword}, '%') OR s.name LIKE CONCAT('%', #{req.keyword}, '%') OR c.name LIKE CONCAT('%', #{req.keyword}, '%') OR d.tags LIKE CONCAT('%', #{req.keyword}, '%'))
AND c.id = #{req.canteenId}
AND s.id = #{req.stallId}
AND d.tags LIKE CONCAT('%', #{req.tag}, '%')
AND d.spice_level = #{req.spiceLevel}
AND d.price >= #{req.minPrice}
AND d.price <= #{req.maxPrice}
ORDER BY (d.view_count*1 + d.rating_count*5*20 + COALESCE(d.avg_rating,0)*20) DESC
ORDER BY d.avg_rating
ASC DESC
ORDER BY d.price
DESC ASC
ORDER BY d.created_at
ASC DESC
ORDER BY d.rating_count DESC, d.avg_rating DESC

SELECT d.id, d.name, d.price, d.images, d.tags, d.description, d.audit_status, d.reject_reason, d.created_at FROM dish d WHERE d.created_by = #{userId}
AND d.audit_status = #{auditStatus}
ORDER BY d.created_at DESC

mapper.update:
UPDATE dish
SET view_count = view_count + 1
WHERE id = #{id}
